CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE public.app_role AS ENUM ('doctor','reception');
CREATE TABLE public.clinics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL DEFAULT 'Modulare — Gestão da Clínica', is_demo boolean NOT NULL DEFAULT false, professional_name text, crm text, rqe text, contact text, address text, retention_policy text NOT NULL DEFAULT 'Sem exclusão automática de registros clínicos. Política a revisar com o responsável.');
GRANT SELECT, UPDATE ON public.clinics TO authenticated; GRANT ALL ON public.clinics TO service_role; ALTER TABLE public.clinics ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid()); CREATE POLICY update_own_profile ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(new.id); RETURN new; END $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, clinic_id uuid NOT NULL REFERENCES public.clinics(id), role public.app_role NOT NULL, UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_clinic_role(c uuid, medical boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND clinic_id=c AND (NOT medical OR role='doctor')) $$;
REVOKE ALL ON FUNCTION public.has_clinic_role(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_clinic_role(uuid,boolean) TO authenticated;
CREATE POLICY clinic_read ON public.clinics FOR SELECT TO authenticated USING(public.has_clinic_role(id)); CREATE POLICY clinic_update ON public.clinics FOR UPDATE TO authenticated USING(public.has_clinic_role(id,true)) WITH CHECK(public.has_clinic_role(id,true));
CREATE TABLE public.patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), identifier text NOT NULL DEFAULT ('P-'||upper(substr(gen_random_uuid()::text,1,8))), name text NOT NULL CHECK(length(trim(name))>1), birth_date date NOT NULL, phone text, email text, address text, guardian text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(clinic_id,identifier), UNIQUE(clinic_id,id));
GRANT SELECT, INSERT, UPDATE ON public.patients TO authenticated; GRANT ALL ON public.patients TO service_role; ALTER TABLE public.patients ENABLE ROW LEVEL SECURITY;
CREATE POLICY patients_read ON public.patients FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id)); CREATE POLICY patients_insert ON public.patients FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id)); CREATE POLICY patients_update ON public.patients FOR UPDATE TO authenticated USING(public.has_clinic_role(clinic_id)) WITH CHECK(public.has_clinic_role(clinic_id));
CREATE TABLE public.services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), name text NOT NULL, duration_minutes integer NOT NULL CHECK(duration_minutes>0), price_cents bigint CHECK(price_cents>=0));
GRANT SELECT, INSERT, UPDATE ON public.services TO authenticated; GRANT ALL ON public.services TO service_role; ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY services_read ON public.services FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id)); CREATE POLICY services_write ON public.services FOR ALL TO authenticated USING(public.has_clinic_role(clinic_id,true)) WITH CHECK(public.has_clinic_role(clinic_id,true));
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), patient_id uuid, professional_id uuid NOT NULL, service text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, modality text NOT NULL CHECK(modality IN ('presencial','teleconsulta','domiciliar')), status text NOT NULL DEFAULT 'agendado' CHECK(status IN ('agendado','confirmado','em atendimento','realizado','faltou','cancelado')), expected_cents bigint CHECK(expected_cents>=0), admin_note text NOT NULL DEFAULT '', is_block boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at), CHECK(is_block OR patient_id IS NOT NULL), FOREIGN KEY(clinic_id,patient_id) REFERENCES public.patients(clinic_id,id), UNIQUE(clinic_id,id), EXCLUDE USING gist(clinic_id WITH =,professional_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE (status NOT IN ('cancelado','faltou')));
GRANT SELECT, INSERT, UPDATE ON public.appointments TO authenticated; GRANT ALL ON public.appointments TO service_role; ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointments_read ON public.appointments FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id)); CREATE POLICY appointments_insert ON public.appointments FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id)); CREATE POLICY appointments_update ON public.appointments FOR UPDATE TO authenticated USING(public.has_clinic_role(clinic_id)) WITH CHECK(public.has_clinic_role(clinic_id));
CREATE TABLE public.audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), actor uuid, event text NOT NULL, entity_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role; ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_read ON public.audit_events FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id,true));
CREATE FUNCTION public.audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_events(clinic_id,actor,event,entity_id,metadata) VALUES(new.clinic_id,auth.uid(),TG_TABLE_NAME||':'||TG_OP,new.id,CASE WHEN TG_TABLE_NAME='appointments' AND TG_OP='UPDATE' THEN jsonb_build_object('old_start',old.starts_at,'new_start',new.starts_at,'old_status',old.status,'new_status',new.status) ELSE '{}'::jsonb END); RETURN new; END $$;
CREATE TRIGGER audit_patients AFTER INSERT OR UPDATE ON public.patients FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER audit_appointments AFTER INSERT OR UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE TABLE public.encounters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), patient_id uuid NOT NULL, appointment_id uuid, author_id uuid NOT NULL DEFAULT auth.uid(), modality text NOT NULL DEFAULT 'presencial', content jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'rascunho' CHECK(status IN ('rascunho','finalizado')), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), finalized_at timestamptz, FOREIGN KEY(clinic_id,patient_id) REFERENCES public.patients(clinic_id,id), FOREIGN KEY(clinic_id,appointment_id) REFERENCES public.appointments(clinic_id,id), UNIQUE(clinic_id,id));
GRANT SELECT, INSERT, UPDATE ON public.encounters TO authenticated; GRANT ALL ON public.encounters TO service_role; ALTER TABLE public.encounters ENABLE ROW LEVEL SECURITY; CREATE POLICY encounter_read ON public.encounters FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id,true)); CREATE POLICY encounter_insert ON public.encounters FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id,true) AND author_id=auth.uid() AND status='rascunho'); CREATE POLICY encounter_update ON public.encounters FOR UPDATE TO authenticated USING(public.has_clinic_role(clinic_id,true) AND author_id=auth.uid()) WITH CHECK(public.has_clinic_role(clinic_id,true) AND author_id=auth.uid());
CREATE TABLE public.encounter_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), encounter_id uuid NOT NULL, content jsonb NOT NULL, version integer NOT NULL, author_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(clinic_id,encounter_id) REFERENCES public.encounters(clinic_id,id));
GRANT SELECT ON public.encounter_versions TO authenticated; GRANT ALL ON public.encounter_versions TO service_role; ALTER TABLE public.encounter_versions ENABLE ROW LEVEL SECURITY; CREATE POLICY versions_read ON public.encounter_versions FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id,true));
CREATE FUNCTION public.protect_encounter() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF old.status='finalizado' THEN RAISE EXCEPTION 'Atendimento finalizado é imutável. Crie um adendo.'; END IF; IF new.clinic_id<>old.clinic_id OR new.patient_id<>old.patient_id OR new.author_id<>old.author_id OR new.appointment_id IS DISTINCT FROM old.appointment_id THEN RAISE EXCEPTION 'Vínculos imutáveis'; END IF; IF new.version<>old.version+1 THEN RAISE EXCEPTION 'Conflito de versão: recarregue antes de salvar'; END IF; new.updated_at=now(); IF new.status='finalizado' THEN new.finalized_at=now(); END IF; INSERT INTO public.encounter_versions(clinic_id,encounter_id,content,version,author_id) VALUES(old.clinic_id,old.id,old.content,old.version,old.author_id); RETURN new; END $$;
CREATE TRIGGER protect_encounters BEFORE UPDATE ON public.encounters FOR EACH ROW EXECUTE FUNCTION public.protect_encounter(); CREATE TRIGGER audit_encounters AFTER INSERT OR UPDATE ON public.encounters FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE TABLE public.addenda (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), encounter_id uuid NOT NULL, author_id uuid NOT NULL DEFAULT auth.uid(), reason text NOT NULL CHECK(length(trim(reason))>0), content text NOT NULL CHECK(length(trim(content))>0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(clinic_id,encounter_id) REFERENCES public.encounters(clinic_id,id));
GRANT SELECT, INSERT ON public.addenda TO authenticated; GRANT ALL ON public.addenda TO service_role; ALTER TABLE public.addenda ENABLE ROW LEVEL SECURITY; CREATE POLICY addenda_read ON public.addenda FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id,true)); CREATE POLICY addenda_insert ON public.addenda FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id,true) AND author_id=auth.uid() AND EXISTS(SELECT 1 FROM public.encounters e WHERE e.id=encounter_id AND e.status='finalizado'));
CREATE TRIGGER audit_addenda AFTER INSERT ON public.addenda FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), patient_id uuid NOT NULL, author_id uuid NOT NULL DEFAULT auth.uid(), kind text NOT NULL, content text NOT NULL, status text NOT NULL DEFAULT 'rascunho' CHECK(status IN ('rascunho','original externo — assinatura não verificada')), storage_path text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(clinic_id,patient_id) REFERENCES public.patients(clinic_id,id));
GRANT SELECT, INSERT ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role; ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY; CREATE POLICY documents_read ON public.documents FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id,true)); CREATE POLICY documents_insert ON public.documents FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id,true) AND author_id=auth.uid()); CREATE TRIGGER audit_documents AFTER INSERT ON public.documents FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE TABLE public.financial_titles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), patient_id uuid, appointment_id uuid, description text NOT NULL, category text NOT NULL, direction text NOT NULL CHECK(direction IN ('receber','pagar')), amount_cents bigint NOT NULL CHECK(amount_cents>0), due_date date NOT NULL, cancelled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(clinic_id,patient_id) REFERENCES public.patients(clinic_id,id), UNIQUE(clinic_id,id), UNIQUE(appointment_id));
GRANT SELECT, INSERT ON public.financial_titles TO authenticated; GRANT ALL ON public.financial_titles TO service_role; ALTER TABLE public.financial_titles ENABLE ROW LEVEL SECURITY; CREATE POLICY titles_read ON public.financial_titles FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id)); CREATE POLICY titles_insert ON public.financial_titles FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id));
CREATE TABLE public.settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), title_id uuid NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents>0), paid_at date NOT NULL, method text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(clinic_id,title_id) REFERENCES public.financial_titles(clinic_id,id), UNIQUE(clinic_id,id));
GRANT SELECT, INSERT ON public.settlements TO authenticated; GRANT ALL ON public.settlements TO service_role; ALTER TABLE public.settlements ENABLE ROW LEVEL SECURITY; CREATE POLICY settlements_read ON public.settlements FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id)); CREATE POLICY settlements_insert ON public.settlements FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id));
CREATE TABLE public.reversals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinic_id uuid NOT NULL REFERENCES public.clinics(id), settlement_id uuid NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents>0), reversed_at date NOT NULL, reason text NOT NULL CHECK(length(trim(reason))>0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(clinic_id,settlement_id) REFERENCES public.settlements(clinic_id,id));
GRANT SELECT, INSERT ON public.reversals TO authenticated; GRANT ALL ON public.reversals TO service_role; ALTER TABLE public.reversals ENABLE ROW LEVEL SECURITY; CREATE POLICY reversals_read ON public.reversals FOR SELECT TO authenticated USING(public.has_clinic_role(clinic_id)); CREATE POLICY reversals_insert ON public.reversals FOR INSERT TO authenticated WITH CHECK(public.has_clinic_role(clinic_id));
CREATE FUNCTION public.validate_money_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE total bigint; already bigint; BEGIN IF TG_TABLE_NAME='settlements' THEN SELECT amount_cents INTO total FROM public.financial_titles WHERE id=new.title_id AND clinic_id=new.clinic_id AND NOT cancelled FOR UPDATE; SELECT coalesce(sum(s.amount_cents),0)-(SELECT coalesce(sum(r.amount_cents),0) FROM public.reversals r JOIN public.settlements ss ON ss.id=r.settlement_id WHERE ss.title_id=new.title_id) INTO already FROM public.settlements s WHERE s.title_id=new.title_id; ELSE SELECT amount_cents INTO total FROM public.settlements WHERE id=new.settlement_id AND clinic_id=new.clinic_id FOR UPDATE; SELECT coalesce(sum(amount_cents),0) INTO already FROM public.reversals WHERE settlement_id=new.settlement_id; END IF; IF total IS NULL OR new.amount_cents+already>total THEN RAISE EXCEPTION 'Valor supera o saldo disponível'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_settlement BEFORE INSERT ON public.settlements FOR EACH ROW EXECUTE FUNCTION public.validate_money_event(); CREATE TRIGGER validate_reversal BEFORE INSERT ON public.reversals FOR EACH ROW EXECUTE FUNCTION public.validate_money_event(); CREATE TRIGGER audit_titles AFTER INSERT ON public.financial_titles FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER audit_settlements AFTER INSERT ON public.settlements FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER audit_reversals AFTER INSERT ON public.reversals FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE FUNCTION public.record_access(c uuid, entity uuid, action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_clinic_role(c,true) THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF action NOT IN ('clinical_access','file_access','export') THEN RAISE EXCEPTION 'Evento inválido'; END IF; INSERT INTO public.audit_events(clinic_id,actor,event,entity_id) VALUES(c,auth.uid(),action,entity); END $$; REVOKE ALL ON FUNCTION public.record_access(uuid,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_access(uuid,uuid,text) TO authenticated;